from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.core.entities.ssh_executor import SshExecutor
from .sherpa_converter import SherpaConverter
from .docker_container import DockerContainer


class SherpaConverterFactory(NamedComponentFactory):
    _product_class = SherpaConverter
    _optional_parameters = {
        "file_path_pattern", "output_path", "sherpa_executable", "sherpa_command_duration",
        "sherpa_command_macro_period"
    }


class RemoteSherpaConverterFactory(Creating("tool_executor", "SshExecutor", "executor"),
                                   Creating("file_putter", "SshFilePutter", "executor"),
                                   Creating("file_getter", "SshFileGetter", "executor"),
                                   SherpaConverterFactory):
    pass


class LocalSherpaConverterFactory(Creating("tool_executor", "LocalExecutor"),
                                  Creating("file_putter", "LocalFilePutter"),
                                  Creating("file_getter", "LocalFileGetter"),
                                  SherpaConverterFactory):
    pass


class SherpaConverterFactorySelector(object):

    def create(self, configuration, existing_arguments):
        if ("docker_container" in existing_arguments and isinstance(
                existing_arguments["docker_container"].tool_executor, SshExecutor)):
            managed_ssh_connection = \
                existing_arguments["docker_container"].tool_executor.managed_ssh_connection
            configuration["executor"] = self.get_executor(managed_ssh_connection)
        if "executor" in configuration:
            return RemoteSherpaConverterFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        else:
            return LocalSherpaConverterFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)

    def get_executor(self, managed_ssh_connection):
        executor = {}
        for key in ("host", "user", "password", "port", "proxy"):
            value = getattr(managed_ssh_connection, key, None)
            if value is not None:
                if key == "proxy":
                    executor[key] = self.get_executor(value)
                else:
                    executor[key] = value
        return executor


class DockerContainerFactory(NamedComponentFactory):
    _product_class = DockerContainer
    _optional_parameters = {
        "sherpa_image", "docker_port1", "docker_port2", "docker_v1_mount",
        "sherpa_licence", "tool_licence_path", "container_start_timeout"
    }


class RemoteDockerContainerFactory(Creating("tool_executor", "SshExecutor", "executor"),
                                   DockerContainerFactory):
    pass


class LocalDockerContainerFactory(Creating("tool_executor", "LocalExecutor"),
                                  DockerContainerFactory):
    pass


class DockerContainerFactorySelector(object):

    def create(self, configuration, existing_arguments):
        if "executor" in configuration:
            return RemoteDockerContainerFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
        else:
            return LocalDockerContainerFactory().create(
                configuration=configuration,
                existing_arguments=existing_arguments)
